function solve(candidates, target) {
  const nums = candidates.slice().sort((a, b) => a - b);
  const values = [];
  const counts = [];
  for (const v of nums) {
    if (values.length > 0 && values[values.length - 1] === v) counts[counts.length - 1]++;
    else { values.push(v); counts.push(1); }
  }
  const results = [];
  const combo = [];
  function record(gi, remaining) {
    if (remaining === 0) { results.push(combo.slice()); return; }
    if (gi === values.length || remaining < 0) return;
    const value = values[gi];
    for (let take = 0; take <= counts[gi] && take * value <= remaining; take++) {
      for (let t = 0; t < take; t++) combo.push(value);
      record(gi + 1, remaining - take * value);
      for (let t = 0; t < take; t++) combo.pop();
    }
  }
  record(0, target);
  results.sort((a, b) => {
    const len = Math.min(a.length, b.length);
    for (let i = 0; i < len; i++) { if (a[i] !== b[i]) return a[i] - b[i]; }
    return a.length - b.length;
  });
  return results;
}

function solve(candidates, target) {
  const nums = candidates.slice().sort((a, b) => a - b);
  const results = [];
  const combo = [];
  function backtrack(index, remaining) {
    if (remaining === 0) { results.push(combo.slice()); return; }
    for (let i = index; i < nums.length; i++) {
      if (i > index && nums[i] === nums[i - 1]) continue;
      if (nums[i] > remaining) break;
      combo.push(nums[i]);
      backtrack(i + 1, remaining - nums[i]);
      combo.pop();
    }
  }
  backtrack(0, target);
  results.sort((a, b) => {
    const len = Math.min(a.length, b.length);
    for (let i = 0; i < len; i++) { if (a[i] !== b[i]) return a[i] - b[i]; }
    return a.length - b.length;
  });
  return results;
}
